OrderOrbit.define("bundles",function(e,s,o){var a=e.content,c=a.products||[],t=Number(a.min_items||1),n=Math.min(t,c.length),i=Math.max(0,t-n),l=c.map(function(e,c){return'<label class="oo-tile"><input type="checkbox" '+(c<t?"checked":"")+" data-oo-select>"+o.productImage(e)+'<span class="oo-name">'+o.esc(e.title)+"</span>"+(null!=e.price?'<span class="oo-price">'+(a.show_compare_at&&e.compare_at?"<s>"+o.esc(o.money(e.compare_at,s.currency))+"</s> ":"")+o.esc(o.money(e.price,s.currency))+"</span>":"")+"</label>"}).join("")||'<p class="oo-empty">Choose products for this bundle.</p>';return'<div class="oo-body">'+(a.badge?'<span class="oo-badge">'+o.esc(a.badge)+"</span>":"")+'<p class="oo-title">'+o.esc(a.headline)+"</p>"+(a.subheadline?'<p class="oo-sub">'+o.esc(a.subheadline)+"</p>":"")+'<div class="oo-tiles">'+l+'</div><p class="oo-message">'+(i?o.fill(a.progress_message,{remaining:i}):"Saving unlocked")+'</p><div class="oo-progress"><i style="width:'+(t?Math.min(100,n/t*100):100)+'%"></i></div><button type="button" class="oo-btn" data-oo-click="bundle_add"'+(i?" disabled":"")+">"+o.esc(a.cta_text)+"</button></div>"});
